void Solver::bump_var(int var, double coeff) {
    // Increase activity of variable 'var' by a scaled increment.
    double delta = var_inc * coeff;
    activity[var] += delta;

    // If any activity becomes excessively large, rescale all activities to avoid overflow.
    const double MAX_ACTIVITY = 1e150;
    const double RESCALE_FACTOR = 1e-150;
    if (activity[var] > MAX_ACTIVITY) {
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= RESCALE_FACTOR;
        }
        var_inc *= RESCALE_FACTOR;
    }

    // Keep the VSIDS priority queue up‑to‑date.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
